CREATE POLICY qualified_portfolio ON public.bundle AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_qualified_investor()) WITH CHECK(public.is_qualified_investor());
CREATE POLICY qualified_portfolio_items ON public.bundle_item AS RESTRICTIVE FOR ALL TO authenticated USING(public.is_qualified_investor()) WITH CHECK(public.is_qualified_investor());
CREATE OR REPLACE FUNCTION public.project_identity(_project_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE p public.project;d public.developer_profiles;BEGIN IF auth.uid() IS NULL OR NOT (private.owns_project(auth.uid(),_project_id) OR private.has_project_access(auth.uid(),_project_id)) THEN RETURN NULL;END IF;SELECT * INTO p FROM public.project WHERE id=_project_id;SELECT * INTO d FROM public.developer_profiles WHERE id=p.developer_id;RETURN jsonb_build_object('title',p.title,'city',p.city,'country',p.country_code,'developer',jsonb_build_object('name',d.company_name,'contactName',d.full_name,'position',d.position));END $$;
REVOKE ALL ON FUNCTION public.project_identity(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.project_identity(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.preview_investor_document(_document jsonb,_banded boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE='42501';END IF;IF jsonb_typeof(_document->'answers')<>'object' OR jsonb_typeof(_document->'rows')<>'object' OR octet_length(_document::text)>250000 THEN RAISE EXCEPTION 'Invalid preview document';END IF;RETURN public.investor_document(_document,_banded);END $$;
REVOKE ALL ON FUNCTION public.preview_investor_document(jsonb,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.preview_investor_document(jsonb,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.project_pdf_inputs(_project_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE p public.project;t jsonb;info jsonb;recipient text;BEGIN IF NOT public.is_qualified_investor() THEN RAISE EXCEPTION 'Complete your investment mandate to open this' USING ERRCODE='42501';END IF;SELECT * INTO p FROM public.project WHERE id=_project_id AND visibility='listed';IF p.id IS NULL THEN RAISE EXCEPTION 'Listing unavailable';END IF;SELECT to_jsonb(r) INTO t FROM public.project_teaser_rows() r WHERE r.id=_project_id;info:=public.investor_project(_project_id);SELECT full_name INTO recipient FROM public.investor_profiles WHERE user_id=auth.uid();RETURN jsonb_build_object('teaser',t,'information',info,'identity',public.project_identity(_project_id),'recipient',coalesce(nullif(btrim(recipient),''),'Investor '||auth.uid()::text),'generatedAt',now(),'asOf',coalesce(p.financial_as_of,p.technical_as_of),'reference',p.id);END $$;
REVOKE ALL ON FUNCTION public.project_pdf_inputs(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.project_pdf_inputs(uuid) TO authenticated;
DO $patch$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.investor_document(jsonb,boolean)'::regprocedure) INTO d;d:=replace(d,'''version'',''subscriber-projection-1''','''version'',''investor-projection-1''');EXECUTE d;END $patch$;